print("earlier", sum(a.values()), len(a), "now", sum(b.values()), len(b), "claude", sum(c.values()))
for k in sorted(b):
    if a.get(k) != b[k] or b[k] < 3 or c.get(k, 3) < 3: print(f"{k:36} {a.get(k)} {b[k]} {c.get(k)}")
